// scala-cqrs-es.test.mjs — inc3 gate: golden-master byte identity against LIVE CodegenMain
// output (eight aggregate-skeleton kinds for CreditBalance), plus plan-shape assertions.
// generatorVersion is pinned to the commit that produced the golden tree so the header line
// (`@generated by CodegenMain:<v>`) matches byte-for-byte; that line never participates in
// the internal fingerprint comparison, it is pinned here only to lock the golden.
import { equal, ok } from 'node:assert';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { plan } from '../src/core/generate.mjs';

const GEN = join(import.meta.dirname, '..', 'generators', 'scala-cqrs-es');
const GOLD = join(import.meta.dirname, '..', 'golden', 'scala-cqrs-es');
const GOLDEN_VERSION = 'dbd66fd5';

const { manifest, entries } = await plan({
  canonicalFile: join(GOLD, 'credit-balance.canonical.json'),
  generatorDir: GEN,
  options: { generatorVersion: GOLDEN_VERSION },
});
equal(manifest.name, 'scala-cqrs-es');
equal(entries.length, 8);
const kinds = entries.map((e) => e.kind).sort();
equal(kinds.join(','), 'aggregate-root,behaviors,command-helpers,entity,event-handler,factory,protocol,repository');
for (const e of entries) {
  const want = readFileSync(join(GOLD, 'expected', e.path), 'utf8');
  equal(e.content, want, `byte identity: ${e.path}`);
}

// generatorVersion drives ONLY the header line (nothing else moves) — change v, one line differs.
const { entries: other } = await plan({
  canonicalFile: join(GOLD, 'credit-balance.canonical.json'),
  generatorDir: GEN,
  options: { generatorVersion: 'deadbeef' },
});
const diffLines = entries[0].content.split('\n').filter((l, i) => l !== other[0].content.split('\n')[i]);
ok(diffLines.length === 1 && diffLines[0].includes('@generated by CodegenMain:'),
  'generatorVersion changes exactly the @generated header line');

console.log('✅ scala-cqrs-es — golden byte identity (8 aggregate-skeleton kinds, live CodegenMain)');
